With these definitions in minds, we  consider the following initial boundary value problem
for the wave equation
\begin{equation} \left\{
\begin{array}{llll}
\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}v(x,t)=F(x,t)  & \textrm{in }\,\,Q,\cr
v(x,0)=0,\quad\partial_tv(x,0)=0 & \textrm{in }\,\,\mathrm{M},\cr
v(x,t)=0 & \textrm{on } \,\, \Sigma.
\end{array}
\right.
\end{equation}

\left\{
\begin{array}{llll}
\para{\partial_t^2-\Delta+a(x)\partial_t+q(x)}v(x,t)=F(x,t)  & \textrm{in }\,\,Q,\cr
v(x,0)=0,\quad\partial_tv(x,0)=0 & \textrm{in }\,\,\mathrm{M},\cr
v(x,t)=0 & \textrm{on } \,\, \Sigma.
\end{array}
\right.

We may define the Dirichlet to Neumann (D-N) map associated with hyperbolic problem (\ref{1.1}) by
\begin{equation} \Lambda_{a,q}(f)=\partial_\nu u,\quad f\in \mathcal{H}_0^{1}(\Sigma)=\set{f\in H^1(\Sigma),\,\, f(\cdot,0)=0\,\textrm{on}\,\,\partial\mathrm{M}}.
\end{equation}

Let $m_1,m_2>0$ and $\eta> n/2$ be given, set
\begin{equation} \mathscr{A}(m_1,\eta)= \set{a\in W^{2,\infty}(\mathrm{M}),\,\,\norm{a}_{H^\eta(\mathrm{M})}\leq m_1},
\end{equation}
and 
\begin{equation} \mathscr{Q}(m_2)= \set{q\in W^{2,\infty}(\mathrm{M}),\,\,\norm{q}_{H^2(\mathrm{M})}\leq m_2}.
\end{equation}

By
\begin{align*}
S\mathrm{M}=\set{(x,\xi)\in T\mathrm{M};\,\abs{\xi}=1}, \quad
S^*\mathrm{M}=\set{(x,p)\in T^*\mathrm{M};\,\abs{p}=1},
\end{align*}
we denote the sphere bundle and co-sphere bundle of $\mathrm{M}$.

The exponential map $\exp_x:T_x\mathrm{M}\to \mathrm{M}$ is given by
\begin{equation} \exp_x(v)=\gamma_{x,\xi}(\abs{v}),\quad \xi=\frac{v\,\,}{\abs{v}}.
\end{equation}

We say that a compact Riemannian
manifold $(\mathrm{M}, \mathrm{g})$ is simple if it satisfies the following properties
\begin{enumerate}
     \item[(a)] $(\mathrm{M},\mathrm{g})$ is convex and non-trapping, 
     \item[(b)] there are no conjugate points on any geodesic.
\end{enumerate}

This Hilbert space is endowed with the scalar product
\begin{equation} \para{u,v}_\mu=\int_{\partial_+S\mathrm{M}}u(x,\xi) \overline{v}(x,\xi) \mu(x,\xi)\,\mathrm{d\sigma}^{2n-2}.
\end{equation}

The ray transform (also called geodesic $X$-ray transform) on a convex non trapping manifold $\mathrm{M}$ is the linear operator
\begin{equation} \mathcal{I}:\mathcal{C}^\infty(\mathrm{M})\longrightarrow \mathcal{C}^\infty(\partial_+S\mathrm{M}),
\end{equation}
defined by the equality
\begin{equation} \mathcal{I} f(x,\xi)=\int_0^{\ell_+(x,\xi)}f(\gamma_{x,\xi}(t))\, \mathrm{d} t,\quad (x,\xi)\in\partial_+S\mathrm{M}.
\end{equation}

For $(x,\xi)\in T\mathrm{M}$, we set $K(x,\xi)=\underset{\pi \ni \xi}{\sup} K(x,\pi) $ and
\begin{equation} K^+(x,\xi)=\max\{0,K(x,\xi)\}. 
\end{equation}

For a simple compact Riemannian manifold $(\mathrm{M},\mathrm{g})$, we set 
 \begin{equation} k^+(\mathrm{M},\mathrm{g})=\sup\lbrace \int_0^{\ell_+(x,\xi)} tK^+(\gamma_{x,\xi}(t),\dot{\gamma}_{x,\xi}(t)) dt, \; (x,\xi)\in \partial_+S\mathrm{M}\rbrace.
 \end{equation}

We will usually abbreviate (\ref{2.11}) as follows
\begin{equation} u=(u_{j_1,\cdots,j_s}^{i_1,\cdots,i_r}).
\end{equation}

A tensor $u \in T^r_{s,(x,\xi)}(T\mathrm{M})$ of degree $(r,s)$ at a point $(x,\xi)\in T\mathrm{M}$ is called \textit{semibasic} if in some (and so, in any) natural coordinate system, it can be represented as:
\begin{equation} u=u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}.
\end{equation}

Tensor fields on $M$ can be identified with the semibasic tensor fields on $T\mathrm{M}$ whose components are independent of the second argument $\xi$. Thus we obtain the canonical imbedding
\begin{equation} \iota:\mathcal{C}^{\infty}(\tau_s^r \mathrm{M}) \subset \mathcal{C}^{\infty}(\beta_s^r \mathrm{M}).
\end{equation}

